substep.stepxmp:
For example, copy the following JSON code and save it as a local file called
my-ccdt.json:{
        "channel": [
            {
                "name": "QM1.SVRCONN",
                "clientConnection": {
                    "connection": [
                        {
                            "host": "qm1.yourdomain.com",
                            "port": 1414
                        }
                    ],
                    "queueManager": "qm1"
                },
                "transmissionSecurity": {
                    "cipherSpecification": "ANY_TLS13_OR_HIGHER",
                    "certificateLabel": "CN=agent"
                },
                "type": "clientConnection"
            }
        ]
}
